#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "lwan-config.h"

static bool
dump(struct config *config, struct config_line *line, int indent_level)
{
    if (indent_level > 64)
        return false;

    while (config_read_line(config, line)) {
        switch (line->type) {
        case CONFIG_LINE_TYPE_LINE:
            break;

        case CONFIG_LINE_TYPE_SECTION_END:
            if (indent_level == 0)
                return false;

            return true;

        case CONFIG_LINE_TYPE_SECTION:
            if (!dump(config, line, indent_level + 1))
                return false;

            break;
        }
    }

    if (config_last_error(config)) {
        fprintf(stderr,
                "Error while reading configuration file (line %d): %s\n",
                config_cur_line(config), config_last_error(config));
        return false;
    }

    return true;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    static uint8_t static_data[32768];
    struct config *config;
    struct config_line line;
    int indent_level = 0;

    if (size > sizeof(static_data))
        size = sizeof(static_data);
    memcpy(static_data, data, size);

    config = config_open_for_fuzzing(static_data, size);
    if (!config)
        return 1;

    bool dumped = dump(config, &line, indent_level);

    config_close(config);

    return dumped ? 1 : 0;
}

static void *lex_string(struct lexer *lexer)
{
    int chr;

    do {
        chr = next(lexer);

        if (chr == '$' && peek(lexer) == '{') {
            backup(lexer);
            emit(lexer, LEXEME_STRING);

            advance_n(lexer, strlen("{"));

            return lex_variable;
        }
    } while (isstring(chr));

    backup(lexer);
    emit(lexer, LEXEME_STRING);

    return lex_config;
}

static void *lex_error(struct lexer *lexer, const char *msg)
{
    struct lexeme lexeme = {
        .type = LEXEME_ERROR,
        .value = {
            .value = msg,
            .len = strlen(msg)
        }
    };

    emit_lexeme(lexer, &lexeme);

    return NULL;
}

static void *lex_multiline_string(struct lexer *lexer)
{
    char *end = (peek(lexer) == '"') ? "\"\"\"" : "'''";

    advance_n(lexer, strlen("'''") - 1);

    do {
        if (!strncmp(lexer->pos, end, 3)) {
            emit(lexer, LEXEME_STRING);
            lexer->pos += 3;

            return lex_config;
        }
    } while (next(lexer) != '\0');

    return lex_error(lexer, "EOF while scanning multiline string");
}

static bool isvariable(int chr)
{
    return isalpha(chr) || chr == '_';
}

static void *lex_variable_default(struct lexer *lexer)
{
    int chr;

    do {
        chr = next(lexer);

        if (chr == '}') {
            backup(lexer);
            emit(lexer, LEXEME_STRING);

            advance_n(lexer, strlen("}"));

            return lex_config;
        }
    } while (chr != '\0');

    return lex_error(lexer, "EOF while scanning for end of variable");
}

static void *lex_variable(struct lexer *lexer)
{
    int chr;

    advance_n(lexer, strlen("${") - 1);

    do {
        chr = next(lexer);

        if (chr == ':') {
            backup(lexer);
            emit(lexer, LEXEME_VARIABLE_DEFAULT);
            advance_n(lexer, strlen(":"));
            return lex_variable_default;
        }

        if (chr == '}') {
            backup(lexer);
            emit(lexer, LEXEME_VARIABLE);
            advance_n(lexer, strlen("}"));

            return lex_config;
        }
    } while (isvariable(chr));

    return lex_error(lexer, "EOF while scanning for end of variable");
}

static bool iscomment(int chr)
{
    return chr != '\0' && chr != '\n';
}

static void *lex_comment(struct lexer *lexer)
{
    while (iscomment(next(lexer)))
        ;
    backup(lexer);
    return lex_config;
}

static void *lex_config(struct lexer *lexer)
{
    while (true) {
        int chr = next(lexer);

        if (chr == '\0')
            break;

        if (chr == '\n') {
            emit(lexer, LEXEME_LINEFEED);
            return lex_config;
        }

        if (isspace(chr)) {
            ignore(lexer);
            continue;
        }

        if (chr == '{') {
            emit(lexer, LEXEME_OPEN_BRACKET);
            return lex_config;
        }

        if (chr == '}') {
            emit(lexer, LEXEME_CLOSE_BRACKET);
            return lex_config;
        }

        if (chr == '=') {
            emit(lexer, LEXEME_EQUAL);
            return lex_config;
        }

        if (chr == '#')
            return lex_comment;

        if (chr == '\'' && !strncmp(lexer->pos, "''", 2))
            return lex_multiline_string;
        if (chr == '"' && !strncmp(lexer->pos, "\"\"", 2))
            return lex_multiline_string;

        if (chr == '$' && peek(lexer) == '{')
            return lex_variable;

        if (isstring(chr))
            return lex_string;

        return lex_error(lexer, "Invalid character");
    }

    emit(lexer, LEXEME_LINEFEED);
    emit(lexer, LEXEME_EOF);

    return NULL;
}

static bool lex_next(struct lexer *lexer, struct lexeme **lexeme)
{
    while (lexer->state) {
        if (lexeme_buffer_consume(&lexer->buffer, lexeme))
            return true;

        lexer->state = lexer->state(lexer);
    }

    return lexeme_buffer_consume(&lexer->buffer, lexeme);
}

static void *parse_config(struct parser *parser);

#define ENV_VAR_NAME_LEN_MAX 64

static __attribute__((noinline)) const char *secure_getenv_len(const char *key, size_t len)
{
    if (UNLIKELY(len > ENV_VAR_NAME_LEN_MAX)) {
        lwan_status_error("Variable name exceeds %d bytes", ENV_VAR_NAME_LEN_MAX);
        return NULL;
    }
